static float clampf(float v, float a, float b) { return v < a ? a : (v > b ? b : v); }
static int clampi(int v, int a, int b) { return v < a ? a : (v > b ? b : v); }
static float frand(void) { return (float)rand() / (float)RAND_MAX; }
static uint32_t hash2(int x, int y, int s)
{
    uint32_t h = (uint32_t)x * 374761393u + (uint32_t)y * 668265263u + (uint32_t)s * 2246822519u;
    h = (h ^ (h >> 13)) * 1274126177u;
    return h ^ (h >> 16);
}
static inline uint32_t shadeC(uint32_t c, int s)
{
    if (s >= 256) return c | 0xFF000000;
    if (s < 0) s = 0;
    uint32_t rb = ((c & 0xFF00FF) * (uint32_t)s >> 8) & 0xFF00FF;
    uint32_t g = ((c & 0x00FF00) * (uint32_t)s >> 8) & 0x00FF00;
    return 0xFF000000 | rb | g;
}
static inline uint32_t mixC(uint32_t a, uint32_t b, int t)
{
    int ar = (a >> 16) & 255, ag = (a >> 8) & 255, ab = a & 255;
    int br = (b >> 16) & 255, bg = (b >> 8) & 255, bb = b & 255;
    int r = ar + ((br - ar) * t >> 8), g = ag + ((bg - ag) * t >> 8), bl = ab + ((bb - ab) * t >> 8);
    return 0xFF000000 | ((uint32_t)r << 16) | ((uint32_t)g << 8) | (uint32_t)bl;
}
static uint32_t scaleRGB(uint32_t c, float f)
{
    int r = clampi((int)(((c >> 16) & 255) * f), 0, 255), g = clampi((int)(((c >> 8) & 255) * f), 0, 255), b = clampi((int)((c & 255) * f), 0, 255);
    return 0xFF000000 | ((uint32_t)r << 16) | ((uint32_t)g << 8) | (uint32_t)b;
}
static int fogShade(float d) { return (int)(256.f * clampf(1.25f - d * 0.085f, 0.10f, 1.f)); }

