static int fontIdx(char c)
{
    if (c >= 'a' && c <= 'z') c -= 32;
    for (int i = 0; FONT_CHARS[i]; i++) if (FONT_CHARS[i] == c) return i;
    return 0;
}
static void drawTextBuf(uint32_t *buf, int bw, int bh, int x, int y, int sc, uint32_t col, const char *s,
                        int shadow, int cx0, int cy0, int cx1, int cy1)
{
    for (int pass = shadow ? 0 : 1; pass < 2; pass++) {
        int ox = x + (pass == 0 ? (sc + 1) / 2 + 1 : 0), oy = y + (pass == 0 ? (sc + 1) / 2 + 1 : 0);
        uint32_t c = pass == 0 ? 0xFF000000 : col;
        for (const char *p = s; *p; p++, ox += 6 * sc) {
            const unsigned char *g = FONT[fontIdx(*p)];
            for (int r = 0; r < 7; r++)
                for (int b = 0; b < 5; b++)
                    if (g[r] & (0x10 >> b))
                        for (int yy = 0; yy < sc; yy++)
                            for (int xx = 0; xx < sc; xx++) {
                                int px = ox + b * sc + xx, py = oy + r * sc + yy;
                                if (px >= cx0 && px < cx1 && py >= cy0 && py < cy1 && px < bw && py < bh) buf[py * bw + px] = c;
                            }
        }
    }
}
static int textW(const char *s, int sc) { return (int)strlen(s) * 6 * sc - sc; }
static int clipX0 = 0, clipX1 = FBW, clipY0 = 0, clipY1 = FBH;
static void drawText(int x, int y, int sc, uint32_t col, const char *s) { drawTextBuf(fb, FBW, FBH, x, y, sc, col, s, 1, clipX0, clipY0, clipX1, clipY1); }
static void drawTextC(int cx, int y, int sc, uint32_t col, const char *s) { drawText(cx - textW(s, sc) / 2, y, sc, col, s); }
static void fillRect(int x0, int y0, int w, int h, uint32_t c)
{
    for (int y = y0 < clipY0 ? clipY0 : y0; y < y0 + h && y < clipY1; y++)
        for (int x = x0 < clipX0 ? clipX0 : x0; x < x0 + w && x < clipX1; x++) fb[y * FBW + x] = c;
}
static void blendRect(int x0, int y0, int w, int h, uint32_t c, int a)
{
    for (int y = y0 < clipY0 ? clipY0 : y0; y < y0 + h && y < clipY1; y++)
        for (int x = x0 < clipX0 ? clipX0 : x0; x < x0 + w && x < clipX1; x++) fb[y * FBW + x] = mixC(fb[y * FBW + x], c, a);
}

/* ------------------------------------------------------------------ */
/* Wall textures (64x64)                                              */
/* ------------------------------------------------------------------ */
#define TS 64
enum {
    TX_WOOD, TX_STONE, TX_BRICK, TX_PLASTER, TX_METAL, TX_FENCE, TX_CRATE, TX_PILLAR,
    TX_DOOR750, TX_DOOR1000, TX_DOOR1250, TX_DOOR1500,
    TX_BUY_P, TX_BUY_A, TX_BUY_C, TX_BUY_B, TX_BUY_L,
    TX_BENCH, TX_SH_VEST, TX_SH_HANDS, TX_SH_STRAP, TX_SWITCH_OFF, TX_SWITCH_ON,
    TX_WIN0, TX_COUNT = TX_WIN0 + 7
};
static uint32_t tex[TX_COUNT][TS * TS];

static void tRect(uint32_t *t, int x0, int y0, int x1, int y1, uint32_t c)
{
    for (int y = y0; y <= y1; y++) for (int x = x0; x <= x1; x++) if (x >= 0 && y >= 0 && x < TS && y < TS) t[y * TS + x] = c;
}
static void tEllipse(uint32_t *t, int cx, int cy, int rx, int ry, uint32_t c)
{
    for (int y = cy - ry; y <= cy + ry; y++)
        for (int x = cx - rx; x <= cx + rx; x++) {
            float dx = (float)(x - cx) / (rx + 0.5f), dy = (float)(y - cy) / (ry + 0.5f);
            if (dx * dx + dy * dy <= 1.f && x >= 0 && y >= 0 && x < TS && y < TS) t[y * TS + x] = c;
        }
}
static uint32_t noisy(uint32_t c, int x, int y, int seed, int amt)
{
    int n = (int)(hash2(x, y, seed) % (unsigned)(2 * amt + 1)) - amt;
    return shadeC(c, 236 + n);
}
static void woodPlanks(uint32_t *t, uint32_t base, int seed)
{
    for (int y = 0; y < TS; y++)
        for (int x = 0; x < TS; x++) {
            int plank = x / 8;
            uint32_t c = shadeC(base, 200 + (int)(hash2(plank, 0, seed) % 56));
            int grain = (int)((sinf(y * 0.35f + plank * 1.7f + (x % 8) * 0.4f) + 1.f) * 10.f);
            c = shadeC(c, 236 + grain);
            if (x % 8 == 0) c = shadeC(base, 90);
            if ((y + plank * 13) % 32 == 0) c = shadeC(base, 120);
            if (((y + plank * 13) % 32 == 3 || (y + plank * 13) % 32 == 28) && x % 8 == 4) c = 0xFF2A2A2A;
            t[y * TS + x] = noisy(c, x, y, seed, 18);
        }
}
static void blocks(uint32_t *t, uint32_t base, uint32_t mortar, int bw, int bh, int seed, int rough)
{
    for (int y = 0; y < TS; y++)
        for (int x = 0; x < TS; x++) {
            int row = y / bh, off = (row & 1) ? bw / 2 : 0;
            int bx = (x + off) / bw;
            uint32_t c = shadeC(base, 180 + (int)(hash2(bx, row, seed) % 76));
            if (y % bh == 0 || (x + off) % bw == 0) c = mortar;
            else if (y % bh == 1) c = shadeC(c, 280 > 256 ? 256 : 280);
            t[y * TS + x] = noisy(c, x, y, seed + 1, rough);
        }
}
static void plainWall(uint32_t *t, uint32_t base, int seed)
{
    for (int y = 0; y < TS; y++)
        for (int x = 0; x < TS; x++) {
            uint32_t c = noisy(base, x / 2, y / 2, seed, 14);
            if (y > 52) c = shadeC(0xFF4A3828, 200 + (y == 53 ? 50 : 0));   /* skirting board */
            if (hash2(x / 3, y / 5, seed + 9) % 61 == 0) c = shadeC(base, 170); /* stains */
            t[y * TS + x] = c;
        }
}
static void gunShape(uint32_t *t, int kind, uint32_t c)
{
    switch (kind) {
        case 0: tRect(t, 20, 22, 44, 27, c); tRect(t, 22, 28, 27, 38, c); break;
        case 1: tRect(t, 8, 22, 56, 25, c); tRect(t, 8, 26, 50, 28, c); tRect(t, 10, 29, 22, 36, c); break;
        case 2: tRect(t, 14, 22, 50, 28, c); tRect(t, 26, 29, 30, 40, c); tRect(t, 16, 29, 20, 35, c); tRect(t, 50, 24, 56, 26, c); break;
        case 3: tRect(t, 6, 24, 58, 27, c); tRect(t, 20, 18, 36, 21, c); tRect(t, 6, 28, 18, 35, c); break;
        case 4: tRect(t, 8, 22, 54, 29, c); tRect(t, 24, 30, 36, 40, c); tRect(t, 54, 24, 60, 26, c); tRect(t, 10, 30, 18, 36, c); tRect(t, 30, 16, 40, 21, c); break;
    }
}
static void signBoard(uint32_t *t, int seed)
{
    woodPlanks(t, 0xFF6A4A2E, seed);
    tRect(t, 4, 10, 59, 47, 0xFF2A2420);
}
static void signText(uint32_t *t, const char *top, const char *bottom)
{
    if (top) drawTextBuf(t, TS, TS, 32 - textW(top, 1) / 2, 12, 1, 0xFFE8E4D8, top, 0, 0, 0, TS, TS);
    if (bottom) drawTextBuf(t, TS, TS, 32 - textW(bottom, 1) / 2, 50, 1, 0xFFFFE070, bottom, 0, 0, 0, TS, TS);
}
static void buildTextures(void)
{
    woodPlanks(tex[TX_WOOD], 0xFF7A5A3A, 11);
    blocks(tex[TX_STONE], 0xFF77736E, 0xFF34322F, 32, 16, 3, 26);
    blocks(tex[TX_BRICK], 0xFF8A4A36, 0xFF4A443E, 16, 8, 5, 18);
    plainWall(tex[TX_PLASTER], 0xFFB8AE94, 7);
    for (int y = 0; y < TS; y++)
        for (int x = 0; x < TS; x++) {
            uint32_t c = noisy(0xFF5C6268, x, y / 4, 13, 16);
            if (x % 16 == 0) c = 0xFF2C3034;
            if (x % 16 == 1) c = 0xFF80888E;
            if ((y % 32 == 4 || y % 32 == 28) && (x % 16 == 4 || x % 16 == 12)) c = 0xFF2A2C2E;
            if (hash2(x / 4, y / 3, 17) % 23 == 0) c = mixC(c, 0xFF7A4020, 120);   /* rust */
            tex[TX_METAL][y * TS + x] = c;
        }
    /* boundary hedge/fence */
    for (int y = 0; y < TS; y++)
        for (int x = 0; x < TS; x++) {
            uint32_t c = noisy(mixC(0xFF16241A, 0xFF24382A, (int)(hash2(x / 3, y / 3, 21) % 200)), x, y, 22, 30);
            if (y > 40 && (x % 12 < 2)) c = 0xFF3A2C20;
            tex[TX_FENCE][y * TS + x] = c;
        }
    woodPlanks(tex[TX_CRATE], 0xFF8A6A40, 31);
    tRect(tex[TX_CRATE], 0, 0, 63, 5, 0xFF4A3420); tRect(tex[TX_CRATE], 0, 58, 63, 63, 0xFF4A3420);
    tRect(tex[TX_CRATE], 0, 0, 5, 63, 0xFF4A3420); tRect(tex[TX_CRATE], 58, 0, 63, 63, 0xFF4A3420);
    for (int i = 6; i < 58; i++) tRect(tex[TX_CRATE], i - 2, i - 2, i + 2, i + 2, 0xFF4A3420);
    blocks(tex[TX_PILLAR], 0xFF8E8A82, 0xFF4A4642, 64, 12, 41, 22);
    static const int costs[4] = {750, 1000, 1250, 1500};
    for (int k = 0; k < 4; k++) {
        uint32_t *t = tex[TX_DOOR750 + k];
        woodPlanks(t, 0xFF5A3A22, 23 + k);
        tRect(t, 0, 0, 63, 3, 0xFF2A1A10); tRect(t, 0, 60, 63, 63, 0xFF2A1A10);
        tRect(t, 0, 0, 3, 63, 0xFF2A1A10); tRect(t, 60, 0, 63, 63, 0xFF2A1A10);
        tRect(t, 6, 30, 57, 34, 0xFF3A2414);
        tEllipse(t, 50, 38, 2, 2, 0xFFC8A040);
        tRect(t, 10, 8, 53, 22, 0xFF1E140C);
        char b[12]; sprintf(b, "$%d", costs[k]);
        drawTextBuf(t, TS, TS, 32 - textW(b, 1) / 2, 12, 1, 0xFFFFE070, b, 0, 0, 0, TS, TS);
    }
    static const char *const prices[5] = {"$300", "$900", "$1200", "$1500", "$3000"};
    for (int k = 0; k < 5; k++) {
        uint32_t *t = tex[TX_BUY_P + k];
        signBoard(t, 41 + k);
        gunShape(t, k, 0xFFE8E4D8);
        signText(t, NULL, prices[k]);
    }
    /* upgrade bench: anvil and hammer */
    signBoard(tex[TX_BENCH], 51);
    tRect(tex[TX_BENCH], 16, 30, 48, 35, 0xFF9098A0); tRect(tex[TX_BENCH], 26, 36, 38, 44, 0xFF70787E);
    tRect(tex[TX_BENCH], 40, 18, 44, 30, 0xFF8A6038); tRect(tex[TX_BENCH], 34, 16, 50, 20, 0xFFB0B8C0);
    signText(tex[TX_BENCH], "UPGRADE", "BENCH");
    signBoard(tex[TX_SH_VEST], 52);
    tRect(tex[TX_SH_VEST], 22, 22, 42, 44, 0xFF5A6A3A); tRect(tex[TX_SH_VEST], 28, 22, 36, 28, 0xFF2A2420);
    signText(tex[TX_SH_VEST], "VEST", "$2500");
    signBoard(tex[TX_SH_HANDS], 53);
    tEllipse(tex[TX_SH_HANDS], 26, 32, 7, 9, 0xFFC89070); tEllipse(tex[TX_SH_HANDS], 40, 32, 7, 9, 0xFFC89070);
    signText(tex[TX_SH_HANDS], "QUICKHANDS", "$2000");
    signBoard(tex[TX_SH_STRAP], 54);
    tRect(tex[TX_SH_STRAP], 18, 26, 46, 30, 0xFF7A5030); tRect(tex[TX_SH_STRAP], 30, 22, 34, 42, 0xFF7A5030);
    signText(tex[TX_SH_STRAP], "PACK STRAP", "$3000");
    for (int k = 0; k < 2; k++) {
        uint32_t *t = tex[TX_SWITCH_OFF + k];
        blocks(t, 0xFF5C6268, 0xFF2C3034, 32, 32, 61, 10);
        tRect(t, 18, 10, 46, 50, 0xFF30343A); tRect(t, 22, 14, 42, 46, 0xFF1A1C20);
        tRect(t, 30, k ? 16 : 30, 34, k ? 30 : 44, k ? 0xFF60E0FF : 0xFFC03030);
        drawTextBuf(t, TS, TS, 32 - textW("$1000", 1) / 2, 53, 1, 0xFFFFE070, "$1000", 0, 0, 0, TS, TS);
        drawTextBuf(t, TS, TS, 32 - textW("FENCE", 1) / 2, 2, 1, 0xFFE8E4D8, "FENCE", 0, 0, 0, TS, TS);
    }
    for (int n = 0; n <= 6; n++) {
        uint32_t *t = tex[TX_WIN0 + n];
        woodPlanks(t, 0xFF7A5A3A, 11);
        for (int y = 8; y < 56; y++)
            for (int x = 8; x < 56; x++) {
                uint32_t c = mixC(0xFF2A0806, 0xFF7A2208, y * 4);
                if (hash2(x, y, 99) % 97 == 0) c = 0xFFFFA040;
                t[y * TS + x] = c;
            }
        tEllipse(t, 42, 18, 5, 5, 0xFFFF7030);
        tRect(t, 8, 8, 55, 9, 0xFF3A2A1A); tRect(t, 8, 54, 55, 55, 0xFF3A2A1A);
        tRect(t, 8, 8, 9, 55, 0xFF3A2A1A); tRect(t, 54, 8, 55, 55, 0xFF3A2A1A);
        for (int b = 0; b < n; b++) {
            int y0 = 11 + b * 7, tilt = (b & 1) ? 3 : -3;
            for (int x = 2; x < 62; x++) {
                int yy = y0 + (tilt * (x - 32)) / 32;
                for (int d = 0; d < 5; d++)
                    if (yy + d >= 0 && yy + d < TS) t[(yy + d) * TS + x] = noisy(shadeC(0xFF9A7448, d == 0 || d == 4 ? 150 : 250), x, yy + d, 5 + b, 20);
            }
            tRect(t, 4, y0 + 1, 5, y0 + 2, 0xFF2A2A2A); tRect(t, 58, y0 + 1, 59, y0 + 2, 0xFF2A2A2A);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Sprites: 128x128 with alpha, drawn with simple 3D shading           */
/* ------------------------------------------------------------------ */
#define SS 128
enum { ZV_FRAMES = 9 };      /* walk0-3, attack0-1, die0-2 */
enum {
    SP_Z = 0,                         /* 3 variants x 9 */
    SP_CRAWL = 27,                    /* crawl0-1, attack, die0-1 : 5 */
    SP_BLOAT = 32,                    /* walk0-1, attack : 3 */
    SP_BRUTE = 35,                    /* 9 */
    SP_P1 = 44, SP_P2, SP_PDOWN, SP_PU_AMMO, SP_PU_FIRE, SP_PU_GOLD, SP_COUNT
};
static uint32_t *spr[SP_COUNT];
static uint32_t *cur;               /* sprite being drawn */

static void sPix(int x, int y, uint32_t c) { if (x >= 0 && y >= 0 && x < SS && y < SS) cur[y * SS + x] = c; }
static const float LX = -0.45f, LY = -0.55f, LZ = 0.70f;
static void sBall(float cx, float cy, float rx, float ry, uint32_t col, int seed)
{
    for (int y = (int)(cy - ry - 1); y <= (int)(cy + ry + 1); y++)
        for (int x = (int)(cx - rx - 1); x <= (int)(cx + rx + 1); x++) {
            float nx = (x + 0.5f - cx) / rx, ny = (y + 0.5f - cy) / ry, d = nx * nx + ny * ny;
            if (d > 1.f) continue;
            float nz = sqrtf(1.f - d);
            float l = nx * LX + ny * LY + nz * LZ;
            float f = 0.38f + 0.78f * (l > 0 ? l : 0) + (d > 0.85f ? -0.12f : 0.f);
            f = (floorf(f * 4.f) + 0.5f) / 4.f;                      /* 4 flat tones: pixel-art shading */
            uint32_t c = scaleRGB(col, f);
            if (seed) c = noisy(c, x / 2, y / 2, seed, 8);
            sPix(x, y, c);
        }
}
static void sLimb(float x0, float y0, float x1, float y1, float r0, float r1, uint32_t col, int seed)
{
    float len = sqrtf((x1 - x0) * (x1 - x0) + (y1 - y0) * (y1 - y0));
    int steps = (int)(len) + 1;
    for (int i = 0; i <= steps; i++) {
        float t = (float)i / steps;
        float r = r0 + (r1 - r0) * t;
        sBall(x0 + (x1 - x0) * t, y0 + (y1 - y0) * t, r, r, col, seed);
    }
}
/* turn a smooth 128px drawing into chunky pixel art: 2x2 blocks plus a 2px dark outline */
static void pixelArt(uint32_t *s)
{
    static uint32_t h[64 * 64];
    for (int y = 0; y < 64; y++)
        for (int x = 0; x < 64; x++) {
            uint32_t pick = 0; int cnt = 0;
            for (int j = 0; j < 2; j++) for (int i = 0; i < 2; i++) { uint32_t c = s[(y * 2 + j) * SS + x * 2 + i]; if (c && c != 0xFF140E0C) { cnt++; if (!pick) pick = c; } }
            h[y * 64 + x] = cnt >= 2 ? pick : 0;
        }
    for (int y = 0; y < 64; y++)
        for (int x = 0; x < 64; x++) {
            uint32_t c = h[y * 64 + x];
            if (!c && ((x > 0 && h[y * 64 + x - 1] && h[y * 64 + x - 1] != 0xFF140E0C) || (x < 63 && h[y * 64 + x + 1] && h[y * 64 + x + 1] != 0xFF140E0C) ||
                       (y > 0 && h[(y - 1) * 64 + x] && h[(y - 1) * 64 + x] != 0xFF140E0C) || (y < 63 && h[(y + 1) * 64 + x] && h[(y + 1) * 64 + x] != 0xFF140E0C))) c = 0xFF140E0C;
            h[y * 64 + x] = c;
        }
    for (int y = 0; y < SS; y++) for (int x = 0; x < SS; x++) s[y * SS + x] = h[(y / 2) * 64 + x / 2];
}
static void sOutline(uint32_t *s)
{
    static uint8_t m[SS * SS];
    memset(m, 0, sizeof(m));
    for (int y = 0; y < SS; y++)
        for (int x = 0; x < SS; x++) {
            if (s[y * SS + x]) continue;
            if ((x > 0 && s[y * SS + x - 1]) || (x < SS - 1 && s[y * SS + x + 1]) || (y > 0 && s[(y - 1) * SS + x]) || (y < SS - 1 && s[(y + 1) * SS + x])) m[y * SS + x] = 1;
        }
    for (int i = 0; i < SS * SS; i++) if (m[i]) s[i] = 0xFF140E0C;
}
/* rotate/scale src into dst around pivot (px,py) placed at (qx,qy) */
static void sTransform(uint32_t *dst, const uint32_t *src, float ang, float sc, float px, float py, float qx, float qy)
{
    memset(dst, 0, SS * SS * 4);
    float ca = cosf(ang), sa = sinf(ang);
    for (int y = 0; y < SS; y++)
        for (int x = 0; x < SS; x++) {
            float dx = (x - qx) / sc, dy = (y - qy) / sc;
            float sx = px + dx * ca + dy * sa, sy = py - dx * sa + dy * ca;
            int ix = (int)sx, iy = (int)sy;
            if (ix >= 0 && iy >= 0 && ix < SS && iy < SS && src[iy * SS + ix]) dst[y * SS + x] = src[iy * SS + ix];
        }
}
typedef struct { uint32_t skin, shirt, pants, hair, shoe; int bald, overalls; } Look;
static void buildDeathFrames(int base)
{
    /* derive falling frames from walk frame 0 */
    sTransform(spr[base + 6], spr[base + 0], -0.25f, 0.95f, 64, 125, 70, 126);
    sTransform(spr[base + 7], spr[base + 0], -0.9f, 0.9f, 64, 125, 88, 126);
    sTransform(spr[base + 8], spr[base + 0], -1.48f, 0.82f, 64, 125, 112, 124);
}
