    sBall(48, 123 - la, 6, 3, 0xFF141010, 0);
    sLimb(78, 86, 80, 104 - ra, 7, 5, L->hide, seed); sLimb(80, 104 - ra, 80, 121 - ra, 5, 4, L->hide, seed);
