    sPix(59, 31, 0xFFFF5020); sPix(69, 31, 0xFFFF5020);
    sBall(64, 36, 1.5f, 2.5f, scaleRGB(L->skin, 0.7f), 0);
    /* "their teeth were as the teeth of lions" */
